import fs from 'node:fs/promises';
import path from 'node:path';
import extraSpokes from './spokes-extra.mjs';

const root=process.cwd();
const brand={name:"Dad's Moving & Storage Inc.",address:'3-B Sunblest Compound, Km. 23 West Service Road, Bo. Cupang, Muntinlupa City 1771 Metro Manila',phone:'+63 917 123 3273'};
const logo='/wp-content/uploads/2019/03/Dads-Moving-Storage-Inc.svg';
const defaultHero='/wp-content/uploads/2025/07/dads-office-crew-2024.jpeg';

const routeFile=(route)=>route==='/'?'index.html':route.endsWith('.html')?route.replace(/^\//,''):`${route.replace(/^\//,'').replace(/\/$/,'')}/index.html`;
const rel=(from,to)=>{let r=path.posix.relative(path.posix.dirname(routeFile(from)),routeFile(to));return r.startsWith('.')?r:`./${r}`};
const asset=(from,target)=>{let r=path.posix.relative(path.posix.dirname(routeFile(from)),target.replace(/^\//,''));return r.startsWith('.')?r:`./${r}`};
const esc=(s)=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fitMeta=(raw)=>{let s=raw.trim().replace(/\s+/g,' ');const add=[" Plan with Dad's Moving.",' Book a free pre-move survey.',' Get a written estimate.'];for(const x of add)if(s.length<145)s+=x;if(s.length>160){s=s.slice(0,159);s=s.slice(0,s.lastIndexOf(' ')).replace(/[,:;\- ]+$/,'')+'.'}return s;};
const qSchema=(faqs)=>faqs.map(([name,text])=>({'@type':'Question',name,acceptedAnswer:{'@type':'Answer',text:text.replace(/<[^>]+>/g,'')}}));
const orgSchema={
  '@type':['MovingCompany','LocalBusiness'],name:brand.name,url:'https://dadsmoving.com/',
  address:{'@type':'PostalAddress',streetAddress:'3-B Sunblest Compound, Km. 23 West Service Road, Bo. Cupang',addressLocality:'Muntinlupa City',postalCode:'1771',addressRegion:'Metro Manila',addressCountry:'PH'},
  areaServed:['Metro Manila','Philippines'],memberOf:{'@type':'Organization',name:'International Association of Movers'},
  aggregateRating:{'@type':'AggregateRating',ratingValue:'5',bestRating:'5',reviewCount:'12'}
};

function reviewBar(route,state){return `<div class="ai-review-bar" role="region" aria-label="AI SEO review controls"><div class="ai-review-context"><a class="ai-review-home" href="${asset(route,'index-review.html')}">Review index</a><span class="ai-review-state ai-review-state--${state.toLowerCase()}">${state}</span><span class="ai-review-path">${esc(route)}</span></div><label class="ai-review-toggle"><span>Show AI-SEO / Audit notes</span><input type="checkbox" data-ai-notes-toggle checked role="switch"><span class="ai-review-switch" aria-hidden="true"></span></label></div>`}
function note(title,body){return `<aside class="ai-review-note"><strong>${esc(title)}</strong>${body}</aside>`}
function schemaTag(data){return `<script type="application/ld+json">${JSON.stringify(data).replace(/<\//g,'<\\/')}</script>`}
function header(route){return `<header class="site-header"><div class="site-header__inner"><a href="${rel(route,'/')}"><img class="site-logo" src="${asset(route,logo)}" alt="Dad's Moving and Storage"></a><nav class="site-nav" aria-label="Primary"><a href="${rel(route,'/local-moves/')}">Local moves</a><a href="${rel(route,'/international-moves/')}">International</a><a href="${rel(route,'/office-movers-manila/')}">Office moves</a><a href="${rel(route,'/storage-solutions/')}">Storage</a><a href="${rel(route,'/get-a-quote/')}">Get a quote</a></nav></div></header>`}
function footer(route){return `<footer class="site-footer"><div class="site-footer__inner"><div><b>${brand.name}</b><br>${brand.address}</div><div><a href="${rel(route,'/faqs/')}">FAQs</a> · <a href="${asset(route,'index-review.html')}">AI-SEO review index</a><br>Internal review clone — not the live website.</div></div></footer>`}
function page({route,title,meta,h1,lede,state='NEW',hero=defaultHero,quick='',body='',faqs=[],schemas=[],annotation=''}){
  const faqBlock=faqs.length?`<section class="faq" id="faqs"><h2>Frequently asked questions</h2>${faqs.map(([q,a])=>`<details><summary>${esc(q)}</summary><p>${a}</p></details>`).join('')}</section>`:'';
  const json=[...schemas];if(faqs.length)json.push({'@context':'https://schema.org','@type':'FAQPage',mainEntity:qSchema(faqs)});
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>${esc(title)}</title><meta name="description" content="${esc(fitMeta(meta))}"><link rel="stylesheet" href="${asset(route,'review-assets/review.css')}">${json.map(schemaTag).join('')}</head><body class="review-site">${reviewBar(route,state)}${header(route)}<section class="hero" style="background-image:url('${asset(route,hero)}')"><div class="hero__inner"><span class="ai-review-state ai-review-state--${state.toLowerCase()}">${state}</span><h1>${h1}</h1><p>${lede}</p></div></section>${quick?`<section class="quick-answer" aria-label="Quick answer"><h2>Quick answer</h2>${quick}</section>`:''}<main>${annotation?note('What changed and why',annotation):''}<div class="content-grid"><article>${body}${faqBlock}<section class="cta-band"><h2>Plan the move around your real constraints</h2><p>Start with a free pre-move survey. Dad's will verify access, volume, protection, staffing, and timing before issuing a written estimate.</p><div class="button-row"><a class="button" href="${rel(route,'/get-a-quote/')}">Book a free survey</a><a class="button button--light" href="${rel(route,'/contact-us/')}">Contact the team</a></div></section></article><aside class="side-nav"><strong>Explore the review</strong><a href="${rel(route,'/office-movers-manila/')}">Office movers cornerstone</a><a href="${rel(route,'/blog/office-relocation-manila-complete-guide/')}">Complete relocation guide</a><a href="${rel(route,'/faqs/')}">Moving and storage FAQs</a><a href="${asset(route,'index-review.html')}">All reviewed URLs</a></aside></div></main>${footer(route)}<script src="${asset(route,'review-assets/review.js')}" defer></script></body></html>`;
}
async function writeRoute(route,html){const file=path.join(root,...routeFile(route).split('/'));await fs.mkdir(path.dirname(file),{recursive:true});await fs.writeFile(file,html,'utf8')}

const serviceFaq={
  local:[['How long does a local move in Metro Manila take?','Most condo or small-house moves finish in one day after a survey confirms volume, building access, and travel time. Larger homes may need a separate packing day.'],['Do you coordinate elevator bookings?','Yes. The move plan records each building’s loading bay, service-elevator window, gate-pass requirements, and contact person before move day.'],['Is packing included?','Professional packing can be included in the written scope, along with delivery, unpacking, and debris removal.']],
  international:[['How far ahead should I book?','Allow 6–8 weeks for a survey, export packing, customs documents, and destination-specific checks. Strict biosecurity destinations may need longer.'],['Do you manage customs paperwork?','Dad’s coordinates Philippine export formalities and destination import requirements with its international partner network. Final requirements depend on route and visa status.'],['Can I ship less than a container?','Yes. LCL shipping prices shared container space by volume and is often suitable for smaller households.']],
  storage:[['Can Dad’s collect items for storage?','Yes. The team can pack, collect, inventory, transport, and place items into the appropriate warehouse storage arrangement.'],['What security is in place?','The existing facility description lists 24/7 CCTV, roving guards, a compound night curfew, hydrant and hose systems, and fire-brigade-trained warehouse staff.'],['Can businesses store records or equipment?','Yes. Options include records, IT equipment, office furniture, promotional material, stock, machinery, and other commercial items after a scope check.']],
  office:[['Can the move happen over a weekend?','Yes. Weekend or after-hours sequencing is commonly used to protect business hours, subject to building permits, elevator windows, and crew premiums in the written estimate.'],['Do you disconnect and reconnect IT?','The scope can include tagged workstation moves and coordinated reconnection. Server shutdown, network changes, and application validation remain with the client’s authorised IT owners unless separately agreed.'],['Does the move include insurance?','Coverage and declared-value limits are confirmed in the written proposal. Ask for the policy summary, exclusions, and claims process before approval.']],
  pet:[['How early should pet relocation begin?','Start as early as possible because veterinary tests, import permits, airline space, and quarantine rules can take longer than the household shipment.'],['Is airport transport included?','The current service includes residence pickup and air-conditioned transport to the Manila international airport cargo terminal when included in the confirmed route plan.'],['Will I receive updates?','Dad’s existing service promise includes schedule updates and photos while the pet is in its care.']],
  ubox:[['What is U-Box storage?','It is a mobile storage option: a container is delivered for loading, collected, stored, and redelivered when the destination is ready.'],['Is it suitable during renovation?','Yes. It can reduce repeated handling when furniture needs to leave a room or property temporarily.'],['How is the price calculated?','The written estimate depends on the number of containers, collection and delivery access, handling, and storage duration.']]
};

const services=[
  {route:'/local-moves/',title:'Local Movers in Manila — Careful Door-to-Door Moves',h1:'Local Movers in Manila — Careful, Surveyed Moves',meta:'Plan a local move in Metro Manila with packing, building coordination, transport, unpacking, and a written scope built from a pre-move survey.',lede:'A local move is planned around the actual inventory, access rules, crew hours, and Metro Manila travel window—not a generic truck booking.',quick:'<p>Most Metro Manila condo and small-house moves can be packed and delivered within <strong>one planned move day</strong>, while larger homes may need a separate packing day. Final duration and cost depend on surveyed volume, stairs or elevators, travel distance, and building time windows.</p>',body:'<h2>A local move built from the survey</h2><p>Dad’s starts by recording rooms, fragile pieces, access points, parking, elevator windows, and destination placement. That inventory becomes the basis for crew size, vehicle allocation, packing materials, and the written estimate.</p><h2>What the service can include</h2><ul><li>Professional packing with room and destination labels</li><li>Condo gate passes, loading-bay and elevator coordination</li><li>Padded transport, delivery, unpacking, and debris removal</li><li>Separate handling for artwork, IT equipment, and oversize furniture</li></ul><h2>Metro Manila timing</h2><p>Traffic is treated as a schedule input. A Makati-to-BGC move may be geographically short but still depends on loading-bay windows and EDSA or C5 conditions; the move plan works backwards from the destination slot.</p>',faqs:serviceFaq.local,hero:'/wp-content/uploads/2022/06/local-moves-hero.jpg'},
  {route:'/international-moves/',title:'International Movers Manila — Door-to-Door Support',h1:'International Movers in Manila — Door-to-Door Support',meta:'Plan an international move from Manila with export packing, customs coordination, destination partners, and a route-specific written estimate.',lede:'International household moves combine export packing, customs documentation, freight, destination clearance, delivery, and unpacking through Dad’s IAM partner network.',quick:'<p>Allow roughly <strong>6–10 weeks for many sea-freight household moves</strong>, but route, sailing schedule, customs, biosecurity, and shipment size can shift that range. The pre-move survey confirms volume and identifies destination rules before packing begins.</p>',body:'<h2>One route plan, not a generic five-step script</h2><p>The current journey begins with the shipment itself: what is moving, the destination, visa position, time constraints, and items that may trigger inspection. Dad’s then coordinates origin packing and export formalities with a vetted destination partner for clearance and final delivery.</p><h2>What door-to-door covers</h2><ul><li>Volume survey and route-specific quotation</li><li>Export-standard packing and itemised inventory</li><li>Philippine export and destination import coordination</li><li>Sea or air freight, final delivery, unpacking, and debris removal as scoped</li></ul><h2>IAM network and 196-country reach</h2><p>Dad’s is a member of the International Association of Movers. That network supports handoffs to professional destination agents while keeping one accountable origin contact for the client.</p>',faqs:serviceFaq.international,hero:'/wp-content/uploads/2022/05/international-moves.jpg'},
  {route:'/storage-solutions/',title:'Storage Solutions Manila — Secure Collection Included',h1:'Storage Solutions in Manila — Secure, Collected, Managed',meta:'Store household goods, records, IT equipment, office furniture, and stock in Manila with collection, inventory, security, and flexible terms.',lede:'Dad’s provides warehouse storage with packing and collection, including options for household goods, records, IT equipment, office furniture, and commercial stock.',quick:'<p>Storage pricing depends on <strong>occupied volume, handling, protection requirements, and duration</strong>. Dad’s can collect and pack items, then place them into regular warehouse, climate-controlled, private-room, records, or commercial storage after confirming suitability.</p>',body:'<h2>Choose storage by item, not by label</h2><p>Household furniture, art, records, electronics, machinery, and inventory do not share the same handling needs. The survey identifies moisture sensitivity, retrieval frequency, declared value, and access requirements before the storage method is selected.</p><h2>Facility protections described on the current site</h2><p>The facility description includes 24/7 CCTV, roving guards, a night curfew, two dedicated hydrant-and-hose systems, and staff trained by the Muntinlupa Fire Brigade. Insurance and any climate-control requirement should be confirmed in writing for the specific inventory.</p><h2>Business use cases</h2><p>Records retrieval, office-decommission staging, IT equipment, promotional materials, e-commerce stock, construction materials, automotive parts, and white goods can be scoped without forcing everything into palletised storage.</p>',faqs:serviceFaq.storage,hero:'/wp-content/uploads/2022/06/storage-solutions-hero.jpg'},
  {route:'/officemoves/',title:'Office Moves Manila — Proposed Cornerstone Transition',h1:'Office Moves in Manila — Current Page, Clearer Next Step',meta:'Review the restructured Dad’s office-moves page, its direct answer, schema, and proposed canonical transition to the Manila service cornerstone.',lede:'Dad’s existing office-moves offer combines project management, packing, IT relocation, storage, furniture installation, refurbishment, and reinstatement.',quick:'<p>Most office moves are priced after a site survey because workstations, IT assets, building permits, loading windows, protection, and after-hours labour determine the plan. This URL remains reviewable, but the proposal makes <a href="../office-movers-manila/">/office-movers-manila/</a> the primary service cornerstone.</p>',body:'<h2>Why this page is being consolidated</h2><p>The live `/office-moves-revised/` request now redirects to `/officemoves/`. Rather than maintain two competing office-service URLs, the proposal retains this page during review and points production canonical and redirect decisions toward one deeper cornerstone.</p><h2>Current service scope worth preserving</h2><ul><li>Dedicated office move specialist and project manager</li><li>Protection and bespoke packing for specialist equipment</li><li>IT relocation, furniture reassembly, and commercial storage</li><li>Office refurbishment and leased-space reinstatement</li></ul><h2>Production transition note</h2><p>Before any production redirect, preserve campaign links and analytics, map both historic slugs, and confirm the final canonical. This clone performs no redirect and touches no live system.</p>',faqs:serviceFaq.office,hero:'/wp-content/uploads/2025/07/dads-office-crew-2024.jpeg'},
  {route:'/pet-relocation/',title:'Pet Relocation Philippines — Safe Route Coordination',h1:'Pet Relocation to and from the Philippines',meta:'Coordinate permits, veterinary documents, flights, airport transport, destination partners, and updates for pet relocation to or from the Philippines.',lede:'Pet moves are planned around the animal’s route, veterinary records, airline acceptance, destination permits, and quarantine rules—not the household cargo schedule.',quick:'<p>Begin pet relocation <strong>several months before travel when possible</strong>. Lead time varies sharply by destination: Australia and other strict-entry countries may require tests, permits, and quarantine arrangements well before a flight can be booked.</p>',body:'<h2>Route planning starts with the animal</h2><p>Species, breed, age, medical history, crate dimensions, origin, destination, and target travel date determine the permitted route. Airline heat restrictions and breed rules can matter as much as paperwork.</p><h2>Services shown on the current site</h2><ul><li>Residence pickup and air-conditioned transport to the Manila airport cargo terminal</li><li>Customs and quarantine paperwork support</li><li>IATA-approved travel crates, veterinary clearance, permits, and flight coordination</li><li>Worldwide partner coordination for destination pickup and delivery</li></ul><h2>Owner communication</h2><p>Dad’s existing copy commits to keeping owners informed of the schedule and sharing photos. The written route plan should also identify each handoff and the emergency contact.</p>',faqs:serviceFaq.pet,hero:'/wp-content/uploads/2022/10/pet-relocation-banner.jpg'},
  {route:'/u-box/',title:'U-Box Manila — Mobile Storage with Less Handling',h1:'U-Box Mobile Storage in Manila — Load Once, Move When Ready',meta:'Use mobile U-Box storage in Manila for renovation, staged moves, or delayed handover, with delivery, collection, secure storage, and redelivery.',lede:'U-Box brings the storage container to the property, reducing repeated loading when a move or renovation needs a holding period.',quick:'<p>A U-Box is delivered for loading, collected for storage, and returned when the destination is ready. Suitability and price depend on container quantity, vehicle access, loading help, protection, storage duration, and the final delivery slot.</p>',body:'<h2>Where mobile storage fits</h2><p>It is useful for renovations, lease gaps, staged home moves, and projects where a conventional warehouse transfer would add another handling cycle. Site access must still allow safe container delivery and collection.</p><h2>How the sequence works</h2><ol class="process"><li>Survey access, volume, and protection needs.</li><li>Deliver the mobile container and load to the agreed plan.</li><li>Collect and store the sealed unit.</li><li>Redeliver at the confirmed destination window.</li></ol><h2>What to confirm in the estimate</h2><p>Ask for included loading time, storage term, redelivery area, extension fees, access requirements, prohibited items, and insurance treatment. The clone does not state unverified package prices.</p>',faqs:serviceFaq.ubox,hero:'/wp-content/uploads/2024/03/ubox-dadsmoving.jpg'}
];

