const breadcrumb=(route,name)=>({'@context':'https://schema.org','@type':'BreadcrumbList',itemListElement:[{'@type':'ListItem',position:1,name:'Home',item:'https://dadsmoving.com/'},{'@type':'ListItem',position:2,name,item:`https://dadsmoving.com${route}`} ]});
