async function augmentExisting(route,state){const file=path.join(root,...routeFile(route).split('/'));let html=await fs.readFile(file,'utf8');html=html.replace(/<meta\s+name=['"]robots['"][^>]*>/i,'<meta name="robots" content="noindex,nofollow">');if(!/name=['"]robots/i.test(html))html=html.replace(/<head>/i,'<head><meta name="robots" content="noindex,nofollow">');const css=`<link rel="stylesheet" href="${asset(route,'review-assets/review.css')}">`;if(!html.includes('review-assets/review.css'))html=html.replace(/<\/head>/i,`${css}${route==='/'?schemaTag({'@context':'https://schema.org',...orgSchema}):''}</head>`);let bodyExtra='';if(route==='/'&&!/<h1\b/i.test(html))bodyExtra='<h1 style="position:absolute;left:-10000px">Moving and Storage Services in Manila</h1>';if(route==='/why-choose-us/'&&!/<h1\b/i.test(html))bodyExtra='<h1 style="text-align:center;margin:32px auto">Why Choose Dad’s Moving & Storage</h1>';const msg=existingNotes[route]||`${state==='UNCHANGED'?'No SEO-relevant content change is proposed on this page. Review chrome and crawl blocking are the only additions.':'This page is restructured in the final review set with direct-answer copy, ordered headings, unique metadata, FAQ content, and structured data.'}`;const insert=`${reviewBar(route,state)}${bodyExtra}${note('Review status',esc(msg))}`;html=html.replace(/<body([^>]*)>/i,`<body$1>${insert}`);html=html.replace(/<\/body>/i,`<script src="${asset(route,'review-assets/review.js')}" defer></script></body>`);await fs.writeFile(file,html,'utf8')}

function reviewIndex(rows){const groups=[['Existing live-site pages',rows.filter(r=>r.kind==='existing')],['Cornerstones and hubs',rows.filter(r=>r.kind==='cornerstone'||r.kind==='hub')],['Office move spokes',rows.filter(r=>r.kind==='spoke')],['International, inbound, and FAQ',rows.filter(r=>r.kind==='international')]];const counts=rows.reduce((a,r)=>(a[r.state]=(a[r.state]||0)+1,a),{});return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Dad’s Moving AI-SEO Review Index</title><meta name="description" content="Internal review index for the Dad’s Moving AI-SEO static proposal clone."><link rel="stylesheet" href="review-assets/review.css"></head><body class="review-index">${reviewBar('/index-review.html','NEW')}<header><div><h1>Dad’s Moving AI-SEO review</h1><p>A page-by-page map of the mirrored site, proposed technical fixes, structured data, and complete Office Moves content cluster. Start here; the normal homepage remains available as a reviewed mirror.</p></div></header><main>${note('Crawl safety','Every HTML page carries noindex,nofollow and robots.txt disallows all crawlers. The production recommendation to remove accidental nofollow is shown only as an annotation because this public review must not compete with dadsmoving.com.')}<div class="review-summary"><span><b>${rows.length}</b><br>reviewed URLs</span><span><b>${counts.RESTRUCTURED||0}</b><br>restructured</span><span><b>${counts.NEW||0}</b><br>new</span><span><b>${counts.UNCHANGED||0}</b><br>unchanged</span></div>${groups.map(([name,list])=>`<section class="url-group"><h2>${name}</h2><div class="url-list">${list.map(r=>`<div class="url-row"><span class="ai-review-state ai-review-state--${r.state.toLowerCase()}">${r.state}</span><a href="${asset('/index-review.html',routeFile(r.route))}">${esc(r.route)}</a><small>${esc(r.label)}</small></div>`).join('')}</div></section>`).join('')}</main><script src="review-assets/review.js"></script></body></html>`}

await writeRoute('/office-movers-manila/',cornerstone);
await writeRoute(guideRoute,guide);
for(const hub of hubDefs)await writeRoute(hub.route,hubPage(hub));
for(const def of spokeDefs)await writeRoute(def[1],spokePage(def));
for(const svc of services)await writeRoute(svc.route,page({...svc,state:'RESTRUCTURED',annotation:commonAnnotation,schemas:[serviceSchema(svc.h1,svc.route),breadcrumb(svc.route,svc.h1)]}));
await writeRoute(australiaRoute,australia);await writeRoute(inboundRoute,inbound);await writeRoute(faqRoute,faqPage);
await writeRoute('/office-moves-revised/',page({route:'/office-moves-revised/',title:'Office Moves Revised — Canonical Transition Review',meta:'Review the former office-moves-revised URL, its current redirect destination, and the proposed canonical transition to the Manila office movers cornerstone.',h1:'Office Moves Revised — URL Transition Review',lede:'The live request redirects to /officemoves/. This review preserves the historic audit URL and documents the proposed production transition.',state:'RESTRUCTURED',quick:'<p>Proposed production action: consolidate the historic office-move URLs into <a href="../office-movers-manila/">/office-movers-manila/</a> after redirect, campaign, analytics, and canonical checks. No live redirect is performed by this clone.</p>',annotation:commonAnnotation,body:'<h2>Observed live behaviour</h2><p>On 11 September 2026, a request to <code>/office-moves-revised/</code> resolved to <code>/officemoves/</code>. The baseline commit retains the live /officemoves/ page for exact review.</p><h2>Proposed canonical decision</h2><p>Use one service cornerstone rather than dividing authority across historic slugs. Preserve inbound links with permanent redirects only after the production owner confirms the final map.</p>',faqs:officeFaq.slice(0,2),schemas:[breadcrumb('/office-moves-revised/','Office Moves Revised')]}));
for(const [route,state] of Object.entries(existingStates))if(!services.some(s=>s.route===route)&&route!=='/office-moves-revised/'){
  const current=await fs.readFile(path.join(root,...routeFile(route).split('/')),'utf8');
  if(!current.includes('class="ai-review-bar"'))await augmentExisting(route,state);
}
const rows=[...Object.entries(existingStates).map(([route,state])=>({route,state,kind:'existing',label:existingNotes[route]||'Live-site page with review state.'})),{route:'/office-movers-manila/',state:'NEW',kind:'cornerstone',label:'Transactional office-movers cornerstone.'},{route:guideRoute,state:'NEW',kind:'cornerstone',label:'Complete planning-to-go-live guide.'},...hubDefs.map(h=>({route:h.route,state:'NEW',kind:'hub',label:h.h1})),...spokeDefs.map(s=>({route:s[1],state:'NEW',kind:'spoke',label:s[3]})),{route:australiaRoute,state:'NEW',kind:'international',label:'Manila-to-Australia corridor guide.'},{route:inboundRoute,state:'NEW',kind:'international',label:'Inbound expat and organisation guide.'},{route:faqRoute,state:'NEW',kind:'international',label:'Four-category FAQ hub.'}];
await fs.writeFile(path.join(root,'index-review.html'),reviewIndex(rows),'utf8');
await fs.writeFile(path.join(root,'robots.txt'),'User-agent: *\nDisallow: /\n','utf8');
await fs.writeFile(path.join(root,'llms.txt'),`# Dad's Moving & Storage\n\n> Internal AI-SEO review clone. Do not index.\n\n## Core Services\n- [Local Moves](/local-moves/)\n- [International Moves](/international-moves/)\n- [Storage Solutions](/storage-solutions/)\n- [Office Movers in Manila](/office-movers-manila/)\n- [Pet Relocation](/pet-relocation/)\n- [U-Box](/u-box/)\n\n## Guides\n- [Complete Manila Office Relocation Guide](/blog/office-relocation-manila-complete-guide/)\n- [Moving from Manila to Australia](/international-moves/manila-to-australia/)\n- [Moving to Manila](/international-moves/moving-to-manila/)\n- [Moving and Storage FAQs](/faqs/)\n`,'utf8');
async function allHtml(dir){const out=[];for(const entry of await fs.readdir(dir,{withFileTypes:true})){if(entry.name==='.git'||entry.name==='tmp')continue;const full=path.join(dir,entry.name);if(entry.isDirectory())out.push(...await allHtml(full));else if(entry.name.endsWith('.html'))out.push(full)}return out}
for(const file of await allHtml(root)){
  let html=await fs.readFile(file,'utf8');
  if(!/<meta\s+name=['"]robots['"][^>]*noindex/i.test(html)){
    if(/<meta\s+name=['"]robots['"][^>]*>/i.test(html))html=html.replace(/<meta\s+name=['"]robots['"][^>]*>/i,'<meta name="robots" content="noindex,nofollow">');
    else html=html.replace(/<head>/i,'<head><meta name="robots" content="noindex,nofollow">');
  }
  if(!/<meta\s+[^>]*name=['"]description['"]/i.test(html)){
    const route='/' + path.relative(root,file).replaceAll('\\','/').replace(/index\.html$/,'').replace(/^index\.html$/,'');
    const words=route.replace(/[\/-]+/g,' ').trim()||'Manila moving and storage services';
    html=html.replace(/<\/head>/i,`<meta name="description" content="${esc(fitMeta(`Review ${words} from Dad's Moving and Storage, including the current page, proposed AI-SEO state, technical notes, and linked service information.`))}"></head>`);
  }
  await fs.writeFile(file,html,'utf8');
}
